cat > "$TMPDIR/scan_cast.py" <<'EOF'
import re, os, sys

roots = ["net", "drivers/net"]
# find casts of skb->data to a struct pointer, or assignments ptr = skb->data
cast_re = re.compile(r'\(\s*struct\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*\*?\s*\)\s*(?:skb|[^;]*?)->data')
assign_re = re.compile(r'([a-zA-Z_][a-zA-Z0-9_]*)\s*=\s*(?:[^;]*?)->data\b')
results = []
for top in roots:
    for dirpath, dirs, files in os.walk(top):
        for f in files:
            if not f.endswith('.c'): continue
            p = os.path.join(dirpath, f)
            try:
                lines = open(p, encoding='utf-8', errors='replace').read().split('\n')
            except Exception:
                continue
            for i, l in enumerate(lines):
                if '->data' in l and ('struct' in l or 'memcpy' in l or '=' in l):
                    if 'skb->data' in l or '->data +' in l:
                        results.append((p, i+1, l.strip()[:170]))
for r in results:
    print(f"{r[0]}:{r[1]}: {r[2]}")
print("TOTAL", len(results), file=sys.stderr)
EOF
python3 "$TMPDIR/scan_cast.py" > "$TMPDIR/casts.txt" 2>"$TMPDIR/casts.err"; tail -1 "$TMPDIR/casts.err"; grep -c . "$TMPDIR/casts.txt"

